} derive(Debug)

///| Parse a TOML document string into a `Json` value.
///| Returns a `Json::Object` on success.
pub fn parse_toml(text : String) -> Json raise TomlError {
  let lines = text.split("\n").to_array()
  let mut root : Map[String, Json] = Map::new()
  let mut current_path : Array[String] = []
  let mut line_num = 0

  for line in lines {
    line_num = line_num + 1
    let trimmed = line.trim()
    // skip blank lines and comments
    if trimmed.is_empty() || trimmed.starts_with("#") {
      continue
    }
    // table header
    if trimmed[0] == '[' as Int {
      // find matching close bracket — allow inline comment after `]`
      let end_idx = trimmed.index_of("]")
      if end_idx == -1 {
        raise TomlError::ParseError(
          "line \(line_num): unclosed table header",
        )
      }
      let header_content = trimmed.sub(start=1, end=end_idx).trim()
      if header_content.is_empty() {
        raise TomlError::ParseError(
          "line \(line_num): empty table header",
        )
      }
      current_path = header_content.split(".").map(fn(s) { s.trim() }).to_array()
      for part in current_path {
        if part.is_empty() {
          raise TomlError::ParseError(
            "line \(line_num): empty key in table header",
          )
        }
      }
      // ensure the table path exists in root
      ensure_path(root, current_path, line_num)?
      continue
    }
    // key-value pair
    let eq_idx = trimmed.index_of("=")
    if eq_idx == -1 {
      raise TomlError::ParseError(
        "line \(line_num): expected key = value, got '\(trimmed)'",
      )
    }
    let raw_key = trimmed.sub(start=0, end=eq_idx).trim()
    let raw_val = trimmed.sub(start=eq_idx + 1, end=trimmed.length()).trim()
    if raw_key.is_empty() {
      raise TomlError::ParseError(
        "line \(line_num): empty key before '='",
      )
    }
    // parse keys (may be dotted)
    let keys = raw_key.split(".").map(fn(s) { s.trim() }).to_array()
    for k in keys {
      if k.is_empty() {
        raise TomlError::ParseError(
          "line \(line_num): empty segment in key '\(raw_key)'",
        )
      }
    }
    let value = parse_value(raw_val, line_num)?
    set_value(root, current_path, keys, value, line_num)?
  }

  Json::object(root)
}

///| Navigate or create nested objects for a table path.
fn ensure_path(
  root : Map[String, Json],
  path : Array[String],
  line_num : Int
) -> Unit raise TomlError {
  let mut m = root
  for i in 0..<path.length() {
    let segment = path[i]
    if !m.contains(segment) {
      m[segment] = Json::object(Map::new())
    }
    match m[segment] {
      Json::Object(child) => m = child
      _ =>
        raise TomlError::ParseError(
          "line \(line_num): key collision on table '\(segment)'",
        )
    }
  }
}

///| Set a value at a dotted key path relative to a current table path.
fn set_value(
  root : Map[String, Json],
  current_path : Array[String],
  keys : Array[String],
  value : Json,
  line_num : Int
) -> Unit raise TomlError {
  // full path = current_path + keys
  let full_len = current_path.length() + keys.length()
  // navigate to the leaf's parent
  let mut m = root
  for i in 0..<full_len - 1 {
    let segment = if i < current_path.length() {
      current_path[i]
    } else {
      keys[i - current_path.length()]
    }
    if !m.contains(segment) {
      m[segment] = Json::object(Map::new())
    }
    match m[segment] {
      Json::Object(child) => m = child
      _ =>
        raise TomlError::ParseError(
          "line \(line_num): cannot index into non-object",
        )
    }
  }
  let last_key = keys[keys.length() - 1]
  if m.contains(last_key) {
    raise TomlError::DuplicateKey(
      "line \(line_num): duplicate key '\(last_key)'",
    )
  }
  m[last_key] = value
}

///| Parse a TOML value from a trimmed string.
fn parse_value(s : String, line_num : Int) -> Json raise TomlError {
  // string literal
  if s[0] == '"' as Int {
    return parse_string(s, line_num)
  }
  // array
  if s[0] == '[' as Int {
    return parse_array(s, line_num)
  }
  // boolean
  if s == "true" {
    return Json::True
  }
  if s == "false" {
    return Json::False
  }
  // integer (may begin with '-' or digit)
  if s[0] == '-' as Int || (s[0] >= '0' as Int && s[0] <= '9' as Int) {
    return parse_integer(s, line_num)
  }
  raise TomlError::ParseError(
    "line \(line_num): unrecognized value '\(s)'",
  )
}

///| Parse a TOML string value with escape sequences.
fn parse_string(s : String, line_num : Int) -> Json raise TomlError {
  if s.length() < 2 || s[0] != '"' as Int {
    raise TomlError::ParseError(
      "line \(line_num): malformed string",
    )
  }
  let mut buf = StringBuilder::new()
  let mut i = 1
  while i < s.length() {
    let ch = s[i]
    if ch == '"' as Int {
      // end of string
      // any remaining characters after closing quote are invalid for bare strings
      // (could be an inline comment — we already trimmed, so should be end)
      return Json::String(buf.to_string())
    }
    if ch == '\\' as Int {
      i = i + 1
      if i >= s.length() {
        raise TomlError::ParseError(
          "line \(line_num): incomplete escape at end of string",
        )
      }
      let esc = s[i]
      match esc {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ =>
          raise TomlError::ParseError(
            "line \(line_num): invalid escape '\\\(esc)'",
          )
      }
    } else {
      buf.write_char(ch.to_char())
    }
    i = i + 1
  }
  raise TomlError::ParseError(
    "line \(line_num): unterminated string",
  )
}

///| Parse an integer value.
fn parse_integer(s : String, line_num : Int) -> Json raise TomlError {
  let n : Int = @string.from_str(s) catch {
    _ =>
      raise TomlError::ParseError(
        "line \(line_num): invalid integer '\(s)'",
      )
  }
  Json::number(n.to_double(), repr=s)
}

///| Parse an array value: [ item, item, ... ]
fn parse_array(s : String, line_num : Int) -> Json raise TomlError {
  if s.length() < 2 || s[0] != '[' as Int {
    raise TomlError::ParseError(
      "line \(line_num): malformed array",
    )
  }
  if s[s.length() - 1] != ']' as Int {
    raise TomlError::ParseError(
      "line \(line_num): unclosed array",
    )
  }
  let content = s.sub(start=1, end=s.length() - 1).trim()
  if content.is_empty() {
    return Json::Array([])
  }
  // split on commas (naive: commas between values)
  // We need to respect nesting and strings with commas
  // For our subset we can do a simple split that respects
  // top-level commas only (no nested arrays with strings that contain commas... 
  // but let's be careful: strings inside the array can contain commas)
  let items = split_array_elements(content)
  let mut arr : Array[Json] = []
  for item in items {
    let trimmed_item = item.trim()
    if trimmed_item.is_empty() {
      raise TomlError::ParseError(
        "line \(line_num): empty element in array",
      )
    }
    arr.push(parse_value(trimmed_item, line_num)?)
  }
  Json::Array(arr)
}

///| Split array content by top-level commas (respecting strings).
fn split_array_elements(content : String) -> Array[String] {
  let mut result : Array[String] = []
  let mut depth = 0
  let mut in_string = false
  let mut start = 0
  let mut i = 0
  while i < content.length() {
    let ch = content[i]
    if in_string {
      if ch == '\\' as Int {
        i = i + 2
        continue
      }
      if ch == '"' as Int {
        in_string = false
      }
    } else {
      if ch == '"' as Int {
        in_string = true
      } else if ch == '[' as Int {
        depth = depth + 1
      } else if ch == ']' as Int {
        depth = depth - 1
      } else if ch == ',' as Int && depth == 0 {
        result.push(content.sub(start=start, end=i))
        start = i + 1
      }
    }
    i = i + 1
  }
  result.push(content.sub(start=start, end=i))
  result
}
