  "moonbitlang/async/stdio",
  "moonbitlang/core/argparse",
}

supported_targets = "+native"

options(
  "is-main": true,
)

async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin."),
      ],
      positionals=[
        PositionArg("input", default_values=["-"], about="Input TOML file path."),
      ],
    ),
  )

  let stdin_flag = match matches.flags.get("stdin") {
    None => false
    Some(_) => true
  }

  let input_text = if stdin_flag {
    @stdio.stdin.read_all().text()
  } else {
    let path = match matches.values.get("input") {
      None => fail("missing input argument")
      Some(v) => v[0]
    }
    @fs.read_file(path).text()
  }

  let result = try @lib.parse_toml(input_text) catch {
    TomlError::ParseError(msg) => {
      @stdio.stderr.write_string("Parse error: \{msg}\n")
      @async.abort(1)
    }
    TomlError::DuplicateKey(msg) => {
      @stdio.stderr.write_string("Duplicate key: \{msg}\n")
      @async.abort(1)
    }
  }

  @stdio.stdout.write_string(result.stringify())
  @stdio.stdout.write_string("\n")
}
