name = "user/toml"
version = "0.1.0"
preferred_target = "native"

import {
  "moonbitlang/async@0.19.1",
}

///|
/// A checked error type for TOML parsing failures.
suberror TomlError {
  DuplicateKey(String)
  ParseError(String)
} derive(Debug)

///|
/// Convert a TomlError to a human-readable string message.
pub fn TomlError::to_string(self : TomlError) -> String {
  match self {
    TomlError::DuplicateKey(msg) => "Duplicate key: \{msg}"
    TomlError::ParseError(msg) => "Parse error: \{msg}"
  }
}

///|
/// Parse a TOML document string into a `Json` value.
pub fn parse_toml(text : String) -> Json raise TomlError {
  let root = parse_root(text)
  Json::object(root)
}

///|
fn parse_root(text : String) -> Map[String, Json] raise TomlError {
  let root : Map[String, Json] = Map([])
  let mut current_path : Array[String] = []
  let mut line_num = 0

  for raw_line_view in text.split("\n") {
    line_num = line_num + 1
    let line = raw_line_view.trim()
    // skip blank lines and comments
    if line.is_empty() || line.has_prefix("#") {
      continue
    }
    // table header [section] or [section.sub]
    if line.get_char(0) == Some('[') {
      let close = line.find("]")
      if close == None {
        raise TomlError::ParseError("line \{line_num}: unclosed table header")
      }
      let end_idx = close.unwrap()
      let header_content = line.sub(start=1, end=end_idx).trim()
      if header_content.is_empty() {
        raise TomlError::ParseError("line \{line_num}: empty table header")
      }
      current_path = header_content
        .split(".")
        .map(fn(s) { s.trim().to_owned() })
        .to_array()
      for part in current_path {
        if part.is_empty() {
          raise TomlError::ParseError(
            "line \{line_num}: empty key in table header",
          )
        }
      }
      ensure_path(root, current_path, line_num)
      continue
    }
    // key-value pair
    let eq_idx_opt = line.find("=")
    if eq_idx_opt == None {
      raise TomlError::ParseError(
        "line \{line_num}: expected key = value, got '\{line.to_owned()}'",
      )
    }
    let eq_idx = eq_idx_opt.unwrap()
    let raw_key = line.sub(start=0, end=eq_idx).trim()
    let raw_val = line.sub(start=eq_idx + 1, end=line.length()).trim()
    if raw_key.is_empty() {
      raise TomlError::ParseError("line \{line_num}: empty key before '='")
    }
    // parse keys (may be dotted)
    let keys = raw_key.split(".").map(fn(s) { s.trim().to_owned() }).to_array()
    for k in keys {
      if k.is_empty() {
        raise TomlError::ParseError(
          "line \{line_num}: empty segment in key '\{raw_key.to_owned()}'",
        )
      }
    }
    let value = parse_value(raw_val, line_num)
    set_value(root, current_path, keys, value, line_num)
  }

  root
}

///|
/// Navigate or create nested objects for a table path.
fn ensure_path(
  root : Map[String, Json],
  path : Array[String],
  line_num : Int,
) -> Unit raise TomlError {
  let mut m = root
  let mut i = 0
  while i < path.length() {
    let segment = path[i]
    if !m.contains(segment) {
      m[segment] = Json::object(Map([]))
    }
    match m[segment] {
      Json::Object(child) => m = child
      _ =>
        raise TomlError::ParseError(
          "line \{line_num}: key collision on table '\{segment}'",
        )
    }
    i = i + 1
  }
}

///|
/// Set a value at a dotted key path relative to a current table path.
fn set_value(
  root : Map[String, Json],
  current_path : Array[String],
  keys : Array[String],
  value : Json,
  line_num : Int,
) -> Unit raise TomlError {
  let full_len = current_path.length() + keys.length()
  let mut m = root
  let mut i = 0
  while i < full_len - 1 {
    let segment = if i < current_path.length() {
      current_path[i]
    } else {
      keys[i - current_path.length()]
    }
    if !m.contains(segment) {
      m[segment] = Json::object(Map([]))
    }
    match m[segment] {
      Json::Object(child) => m = child
      _ =>
        raise TomlError::ParseError(
          "line \{line_num}: cannot index into non-object",
        )
    }
    i = i + 1
  }
  let last_key = keys[keys.length() - 1]
  if m.contains(last_key) {
    raise TomlError::DuplicateKey(
      "line \{line_num}: duplicate key '\{last_key}'",
    )
  }
  m[last_key] = value
}

///|
/// Parse a TOML value from a trimmed string view.
fn parse_value(sv : StringView, line_num : Int) -> Json raise TomlError {
  // string literal
  if sv.get_char(0) == Some('"') {
    return parse_string(sv, line_num)
  }
  // array
  if sv.get_char(0) == Some('[') {
    return parse_array(sv, line_num)
  }
  // boolean
  if sv.equal_to_string("true") {
    return Json::boolean(true)
  }
  if sv.equal_to_string("false") {
    return Json::boolean(false)
  }
  // integer (may begin with '-' or digit)
  let first = sv.get_char(0)
  if first == Some('-') || is_digit_char(first) {
    return parse_integer(sv.to_owned(), line_num)
  }
  raise TomlError::ParseError(
    "line \{line_num}: unrecognized value '\{sv.to_owned()}'",
  )
}

///|
fn is_digit_char(ch_opt : Char?) -> Bool {
  match ch_opt {
    None => false
    Some(c) => {
      let n = c.to_int()
      n >= '0'.to_int() && n <= '9'.to_int()
    }
  }
}

///|
/// Parse a TOML string value with escape sequences.
fn parse_string(sv : StringView, line_num : Int) -> Json raise TomlError {
  if sv.length() < 2 || sv.get_char(0) != Some('"') {
    raise TomlError::ParseError("line \{line_num}: malformed string")
  }
  let buf = StringBuilder::new()
  let mut i = 1
  while i < sv.length() {
    let ch_opt = sv.get_char(i)
    let ch = match ch_opt {
      None =>
        raise TomlError::ParseError(
          "line \{line_num}: invalid UTF-16 in string",
        )
      Some(c) => c
    }
    if ch == '"' {
      return Json::string(buf.to_string())
    }
    if ch == '\\' {
      i = i + 1
      if i >= sv.length() {
        raise TomlError::ParseError(
          "line \{line_num}: incomplete escape at end of string",
        )
      }
      let esc_opt = sv.get_char(i)
      let esc = match esc_opt {
        None =>
          raise TomlError::ParseError(
            "line \{line_num}: invalid UTF-16 in escape",
          )
        Some(c) => c
      }
      if esc == '"' {
        buf.write_char('"')
      } else if esc == '\\' {
        buf.write_char('\\')
      } else if esc == 'n' {
        buf.write_char('\n')
      } else if esc == 't' {
        buf.write_char('\t')
      } else {
        raise TomlError::ParseError(
          "line \{line_num}: invalid escape '\\\{esc.to_int().to_char()}'",
        )
      }
    } else {
      buf.write_char(ch)
    }
    i = i + 1
  }
  raise TomlError::ParseError("line \{line_num}: unterminated string")
}

///|
/// Parse an integer value.
fn parse_integer(s : String, line_num : Int) -> Json raise TomlError {
  let n : Int = @string.from_str(s) catch {
    _ => raise TomlError::ParseError("line \{line_num}: invalid integer '\{s}'")
  }
  Json::number(n.to_double(), repr=s)
}

///|
/// Parse an array value: [ item, item, ... ]
fn parse_array(sv : StringView, line_num : Int) -> Json raise TomlError {
  if sv.length() < 2 || sv.get_char(0) != Some('[') {
    raise TomlError::ParseError("line \{line_num}: malformed array")
  }
  if sv.get_char(sv.length() - 1) != Some(']') {
    raise TomlError::ParseError("line \{line_num}: unclosed array")
  }
  let content = sv.sub(start=1, end=sv.length() - 1).trim()
  if content.is_empty() {
    return Json::array([])
  }
  let items = split_array_elements(content)
  let arr : Array[Json] = []
  for item in items {
    let trimmed_item = item.trim()
    if trimmed_item.is_empty() {
      raise TomlError::ParseError("line \{line_num}: empty element in array")
    }
    arr.push(parse_value(trimmed_item, line_num))
  }
  Json::array(arr)
}

///|
/// Split array content by top-level commas (respecting strings and brackets).
fn split_array_elements(content : StringView) -> Array[StringView] {
  let result : Array[StringView] = []
  let mut depth = 0
  let mut in_string = false
  let mut start = 0
  let mut i = 0
  while i < content.length() {
    let ch_opt = content.get_char(i)
    let ch = match ch_opt {
      None => {
        i = i + 1
        continue
      }
      Some(c) => c
    }
    if in_string {
      if ch == '\\' {
        i = i + 2
        continue
      }
      if ch == '"' {
        in_string = false
      }
    } else if ch == '"' {
      in_string = true
    } else if ch == '[' {
      depth = depth + 1
    } else if ch == ']' {
      depth = depth - 1
    } else if ch == ',' && depth == 0 {
      result.push(content.sub(start~, end=i))
      start = i + 1
    }
    i = i + 1
  }
  result.push(content.sub(start~, end=i))
  result
}

///|
async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[FlagArg("stdin", long="stdin", about="Read TOML from stdin.")],
      positionals=[
        PositionArg(
          "input",
          default_values=["-"],
          about="Input TOML file path.",
        ),
      ],
    ),
  )

  let stdin_flag = match matches.flags.get("stdin") {
    None => false
    Some(_) => true
  }

  let input_text : String = if stdin_flag {
    @stdio.stdin.read_until("\u0000").unwrap_or("")
  } else {
    let path = match matches.values.get("input") {
      None => fail("missing input argument")
      Some(v) => v[0]
    }
    let file = @fs.open(path, mode=@fs.Mode::ReadOnly) catch {
      _ => {
        @stdio.stderr.write("Error: cannot open file '\{path}'\n")
        return
      }
    }
    file.read_until("\u0000").unwrap_or("")
  }

  let result = @lib.parse_toml(input_text) catch {
    err => {
      @stdio.stderr.write("Error: \{err.to_string()}\n")
      return
    }
  }

  @stdio.stdout.write(result.stringify())
  @stdio.stdout.write("\n")
}

///|
test {
  let toml = "name = \"Orange\"\ncount = 3\nenabled = true\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "[owner]\nname = \"Tom\"\nage = 30\n\n[database]\nhost = \"localhost\"\nport = 5432\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "[owner]\nname = \"Alice\"\n\n[database.settings]\npool_size = 10\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "[server]\nhost = \"example.com\"\nports = [8000, 8001, 8002]\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "title = \"My Config\"\npath = \"C:\\\\Users\\\\test\"\ndesc = \"Line1\\nLine2\"\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "a.b = 1\na.c = 2\n"
  let _json = parse_toml(toml)
}

///|
test {
  let toml = "name = \"test\"\nname = \"dup\"\n"
  let _result = parse_toml(toml) catch { _ => Json::null() }
}

///|
test {
  let toml = "invalid\n"
  let _result = parse_toml(toml) catch { _ => Json::null() }
}

///|
test {
  let toml = "value = [1, 2, 3]\n"
  let _json = parse_toml(toml)
}
